-- IPA SG official past questions: 2016 autumn morning, questions 11-20.
-- Questions/options are from the published IPA paper; answers checked against the official key.
-- Official question PDF: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf
-- Official answer key: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_ans.pdf
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28a-2016-q11','exam-sg','内部不正・管理者統制','standard','single_choice','【2016年度 平成28年秋期 午前 問11】IPA「組織における内部不正防止ガイドライン」に照らして，システム管理者の内部不正を防止する観点から適切な施策はどれか。','[{"id":"a","text":"システム管理者間の会話や情報交換を制限する。"},{"id":"b","text":"システム管理者の操作履歴を本人以外が閲覧することを制限する。"},{"id":"c","text":"システム管理者の長期休暇取得を制限する。"},{"id":"d","text":"夜間・休日のシステム管理者の単独作業を制限する。"}]','"d"','正解はエ。管理者の単独作業を避け，複数人による確認や相互牽制を設けることで内部不正の機会を減らす。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q12','exam-sg','ボットネット・C&Cサーバ','standard','single_choice','【2016年度 平成28年秋期 午前 問12】ボットネットにおけるC&Cサーバの役割はどれか。','[{"id":"a","text":"Webコンテンツをキャッシュし，本来のサーバに代わって利用者へ配信する。"},{"id":"b","text":"遠隔アクセス時にCHAPなどを用いてパスワードの盗聴を防止する。"},{"id":"c","text":"遠隔アクセス時にチャレンジレスポンス方式のワンタイムパスワードを提供する。"},{"id":"d","text":"乗っ取ったコンピュータに不正な操作を命令し，その応答を受け取る。"}]','"d"','正解はエ。C&C（Command and Control）サーバは，ボット化した端末へ命令を送り，その動作を制御する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q13','exam-sg','モバイル端末管理・MDM','standard','single_choice','【2016年度 平成28年秋期 午前 問13】組織が従業員に貸与するスマートフォンを，セキュリティポリシーに従って一元設定し，業務アプリケーション配信や利用状況を管理する仕組みはどれか。','[{"id":"a","text":"BYOD（Bring Your Own Device）"},{"id":"b","text":"ECM（Enterprise Content Management）"},{"id":"c","text":"LTE（Long Term Evolution）"},{"id":"d","text":"MDM（Mobile Device Management）"}]','"d"','正解はエ。MDMは組織のモバイル端末を一元管理し，設定適用やアプリ配信などを行う仕組みである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q14','exam-sg','マルウェア・ルートキット','standard','single_choice','【2016年度 平成28年秋期 午前 問14】サーバにバックドアを作り，侵入の痕跡を隠蔽するなどの機能をもつ不正なプログラムやツールのパッケージはどれか。','[{"id":"a","text":"RFID"},{"id":"b","text":"rootkit"},{"id":"c","text":"TKIP"},{"id":"d","text":"Web beacon"}]','"b"','正解はイ。ルートキットは侵入後の不正な操作を可能にし，その存在や活動を隠す機能を持つことがある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q15','exam-sg','ログ管理・SIEM','standard','single_choice','【2016年度 平成28年秋期 午前 問15】SIEM（Security Information and Event Management）の機能として，最も適切なものはどれか。','[{"id":"a","text":"機密情報を自動的に特定し，社外への持出しに関連する操作を検知・ブロックする。"},{"id":"b","text":"サーバやネットワーク機器などのログを一括管理・分析し，セキュリティ上の脅威を発見して通知する。"},{"id":"c","text":"情報システムの利用を妨げる事象を登録し，解決・復旧まで管理する。"},{"id":"d","text":"ネットワークへの侵入を試みるパケットを検知して通知する。"}]','"b"','正解はイ。SIEMは複数機器のログやイベントを集約・相関分析し，セキュリティ上の兆候を検出する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q16','exam-sg','メールセキュリティ・SPF','standard','single_choice','【2016年度 平成28年秋期 午前 問16】SPF（Sender Policy Framework）を利用する目的はどれか。','[{"id":"a","text":"HTTP通信経路上の中間者攻撃を検知する。"},{"id":"b","text":"LANへのPCの不正接続を検知する。"},{"id":"c","text":"内部ネットワークへの侵入を検知する。"},{"id":"d","text":"メール送信元のなりすましを検知する。"}]','"d"','正解はエ。SPFは送信ドメインのDNS情報を用いて，送信元サーバが許可されたものかを受信側が確認する仕組みである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q17','exam-sg','メール添付・暗号化','standard','single_choice','【2016年度 平成28年秋期 午前 問17】Webメールを使い，秘密情報を含むファイルを社外の宛先へ送信する。ブラウザとWebメールサーバ間はHTTPSだが，その後のメールサーバ間通信は暗号化されない場合がある。このとき適切な添付方法と理由はどれか。','[{"id":"a","text":"ブラウザからWebメールサーバまで暗号化されるので，ファイルは平文のまま添付する。"},{"id":"b","text":"その後の通信が暗号化されない場合があるので，ファイル自体を暗号化して添付する。"},{"id":"c","text":"宛先のPCまで全通信が暗号化されるので，ファイルは平文のまま添付する。"},{"id":"d","text":"サーバ間通信をBase64形式にすれば盗聴できないので，ファイルをBase64でエンコードして添付する。"}]','"b"','正解はイ。HTTPSで保護されるのはブラウザとWebメールサーバ間であり，経路全体の機密性を保証しないため，ファイル自体の暗号化が必要である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q18','exam-sg','マルウェア検知・ビヘイビア法','standard','single_choice','【2016年度 平成28年秋期 午前 問18】ウイルス検出におけるビヘイビア法に分類されるものはどれか。','[{"id":"a","text":"対象に付加された未感染を保証する情報と，検査対象から算出した情報を比較する。"},{"id":"b","text":"検査対象と安全な場所に保管してある原本とを比較する。"},{"id":"c","text":"検査対象のハッシュ値と既知のウイルスファイルのハッシュ値を比較する。"},{"id":"d","text":"検査対象をメモリ上の仮想環境で実行し，その挙動を監視する。"}]','"d"','正解はエ。ビヘイビア法はプログラムを実行した際の振る舞いを監視し，不審な動作からマルウェアを検出する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q19','exam-sg','時刻同期・NTP','standard','single_choice','【2016年度 平成28年秋期 午前 問19】ファイアウォールの内側にある社内サーバの時計を，インターネット上の時刻サーバと同期させる。許可すべき通信プロトコルはどれか。','[{"id":"a","text":"FTP（TCP，ポート21）"},{"id":"b","text":"NTP（UDP，ポート123）"},{"id":"c","text":"SMTP（TCP，ポート25）"},{"id":"d","text":"SNMP（TCP及びUDP，ポート161及び162）"}]','"b"','正解はイ。NTPはネットワーク上の機器の時刻を同期させるためのプロトコルで，通常UDP 123番ポートを使う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q20','exam-sg','自動入力対策・CAPTCHA','standard','single_choice','【2016年度 平成28年秋期 午前 問20】人間には読み取れてもプログラムでは読み取りにくい，ゆがめた画像などから文字を判読・入力させ，自動入力を排除する技術はどれか。','[{"id":"a","text":"CAPTCHA"},{"id":"b","text":"URL"},{"id":"c","text":"QRコード"},{"id":"d","text":"トラックバックping"}]','"a"','正解はア。CAPTCHAは人間と自動プログラムを区別するために用いられるチャレンジ・レスポンス技術である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja');
